{
  "concepts": [
    {
      "conditions": [],
      "definition": "The runtime role owning traversal, dispatch, actor invocation, process supervision, graph-call realisation, runtime facts, event emission and replay, frames, continuations, retry and correction control, closure folds over runtime truth, re-entry after publication boundaries, and lineage and provenance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 591,
          "quote": "ABG owns traversal; dispatch; actor invocation; process supervision;\ngraph-call realisation; runtime facts; runtime event emission and replay;\nframes; continuations; retry and correction control; closure folds over\nruntime truth; re-entry after publish boundaries; lineage and provenance\n(P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FABG",
          "start_line": 587
        }
      ],
      "key": "abg",
      "label": "ABG"
    },
    {
      "conditions": [],
      "definition": "A domain product owning domain asset meaning, graph-function meaning, its published function catalogue, policy overlays, domain query projections, and domain closure and gap interpretation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 597,
          "quote": "The ODD product owns domain asset meaning, graph-function meaning, the\npublished function catalogue, policy overlays, domain query projections,\nand closure and gap interpretation for its domain (P6, P1).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FODD%20product",
          "start_line": 595
        }
      ],
      "key": "odd_product",
      "label": "ODD product"
    },
    {
      "conditions": [],
      "definition": "Service and query layers are possible owners of transport, sessions, routing, browser-safe projection and API surfaces; they are not owners of runtime or continuation truth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 604,
          "quote": "Service or query layers may own transport, sessions, routing,\nbrowser-safe projection and API surfaces. They own neither runtime truth\nnor continuation truth. The real constructive carrier is never hidden\nbehind the word service (P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FQuery%20and%20service%20layers",
          "start_line": 601
        }
      ],
      "key": "service_query_layers",
      "label": "Service and query layers"
    },
    {
      "conditions": [],
      "definition": "A named GraphFunction or lawful graph-function composition is the primary constructive carrier for an operative constructive step.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 622,
          "quote": "Every operative constructive step is carried by one named `GraphFunction`\nor one lawful graph-function composition.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.2%20Graph%20functions%20are%20the%20primary%20constructive%20carrier",
          "start_line": 621
        }
      ],
      "key": "graph_function",
      "label": "GraphFunction"
    },
    {
      "conditions": [],
      "definition": "The GTL module is the operative publication surface for public graph-function carriers, traversed graphs, typed nodes and vectors, and semantic jobs or equivalent outer callable contracts. RefinementBoundary and CandidateFamily are examples of lawful published traversal-boundary surfaces.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 666,
          "quote": "The product must publish the public graph-function carriers, the graph or\ngraphs those carriers traverse, typed node and vector surfaces, and the\nsemantic jobs or equivalent outer callable contracts bound to the public\ncarrier.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.4%20The%20GTL%20module%20is%20the%20operative%20publication%20surface",
          "start_line": 663
        }
      ],
      "key": "gtl_module",
      "label": "GTL module"
    },
    {
      "conditions": [],
      "definition": "One framework-independent constructive homeostasis loop runs from intent lineage and model synthesis through observation to the next lawful action. Its four named functions are synthesize_model, eval_gap, evaluate_next and evaluate_action. It corrects toward required conditions as observations arrive, without guaranteeing convergence or the adequacy of those conditions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 796,
          "quote": "it corrects towards the required conditions as observations arrive,\nguarantees neither convergence nor the adequacy of those conditions, and\nits diagnoses distinguish the four causes named there (P2, P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 794
        }
      ],
      "key": "constructive_evaluation_loop",
      "label": "Constructive evaluation and yield loop"
    },
    {
      "conditions": [],
      "definition": "The loop's carrier vocabulary comprises: IntentLineage, admitted human/imported/prior-product/intent-engine/prior-construction intent with lineage refs, ABG event-log truth that seeds models without inventing actions; ProductAssetModel, desired and known typed assets synthesized from lineage, prior model and admitted product truth, product-owned and published through admitted events and product projection refs, neither runtime fact nor action authority; Worksite, workspace, runtime archive, transform assets, product asset root, profile and observed file/process state, observable substrate without inherent authority; RuntimeEventLog, append-only admitted ABG runtime facts; RuntimeProjection, replay-derived ABG state over log and execution basis; ObservationSnapshot, a read-only runtime/worksite view carried by an ABG evaluator with domain rows; GapPressureRow, product-domain missing/partial/blocked/waiting/ambiguous asset or evidence pressure over admitted observation; TargetObligationBinding, exact gap-to-outcome/bounded-basis/target-assets/required-roles/evidence/admissible-graph-outcomes binding under GTL/ABG action authority; ActionCatalog, published lawful functions, vectors, targets, inputs and eligible outcomes consumed by ABG; NextActionBasis, initial_selection, post_yield_resume, post_close_graph_continuation, post_retry, post_repair, post_reenter, post_reprice or post_block, a dispatch sum type and not a controller; PriorityProjection, deterministic ranking of bound lawful actions under visible policy by ABG evaluator kernel plus product policy; ConstructionIntent, ABG-admitted selected action for one bounded invocation preserving outcome and bounded-basis refs; AdmittedEvidence, admitted worker/process/product/execution/materialization/liveness/postflight evidence under ABG/product admission, never worker self-closure; EdgeFulfillmentLedger, closure evidence and convergence for one edge attempt or version; EdgeClosureDecision, close/yield/retry/repair/re-enter/reprice/block over the ledger; NextActionProjection, an ABG next-action read model over basis and current truth with product policy, selecting only when lawful.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 855,
          "quote": "| `NextActionProjection` | Read model that observes `NextActionBasis` plus current truth and selects a next graph action only when lawful. | ABG next-action evaluation projection with product policy. |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 855
        },
        {
          "end_line": 847,
          "quote": "| `TargetObligationBinding` | Exact binding from gap pressure to the selected Product outcome, any admitted prerequisite or experiment basis, target assets, required roles, evidence refs, and admissible graph outcomes. | Product domain binding over GTL/ABG action authority. |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 847
        }
      ],
      "key": "loop_carrier_vocabulary",
      "label": "Constructive loop carrier vocabulary"
    },
    {
      "conditions": [],
      "definition": "Model-synthesis function: IntentLineage + prior ProductAssetModel + admitted product truth → ProductAssetModel.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 863,
          "quote": "| `synthesize_model` | `IntentLineage + prior ProductAssetModel + admitted product truth` | `ProductAssetModel` | Model synthesis. It may update desired and known typed asset truth. It must not observe the worksite, select work, invoke work, or close work. |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 863
        }
      ],
      "key": "synthesize_model",
      "label": "synthesize_model"
    },
    {
      "conditions": [],
      "definition": "Read-only gap-discovery function: ProductAssetModel + RuntimeEventLog + RuntimeProjection + Worksite → ObservationSnapshot + GapPressureRow, comparing desired typed asset truth with observed reality.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 864,
          "quote": "| `eval_gap` | `ProductAssetModel + RuntimeEventLog + RuntimeProjection + Worksite` | `ObservationSnapshot + GapPressureRow` | Read-only gap discovery. It compares desired model truth to observed reality and emits missing, partial, blocked, waiting, or ambiguous asset pressure. It does not choose work and does not close work. |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 864
        }
      ],
      "key": "eval_gap",
      "label": "eval_gap"
    },
    {
      "conditions": [],
      "definition": "Next-action evaluation takes NextActionBasis, fresh eval_gap, TargetObligationBinding, ActionCatalog and Policy; produces PriorityProjection, NextActionProjection and selected_action, or a typed no-action with its own core result. Selection is invocational data, distinct from construction-intent admission and action-result evaluation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1022,
          "quote": "Selection and its results. `evaluate_next`'s selection of what is\ninvoked next is invocational data (A11) and is not itself a value of the\ncore result algebra of\n[FOUNDATIONS §4 Results](FOUNDATIONS.md#results).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 1019
        }
      ],
      "key": "evaluate_next",
      "label": "evaluate_next"
    },
    {
      "conditions": [],
      "definition": "Action-result evaluation takes ConstructionIntent, AdmittedEvidence, TargetObligationBinding and Policy and produces EdgeFulfillmentLedger and EdgeClosureDecision for the action just taken; it does not choose the next graph action.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 866,
          "quote": "| `evaluate_action` | `ConstructionIntent + AdmittedEvidence + TargetObligationBinding + Policy` | `EdgeFulfillmentLedger + EdgeClosureDecision` | Action-result evaluation. It decides close, yield, retry, repair, re-enter, reprice, or block for the action just taken. It does not choose the next graph action. |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 866
        }
      ],
      "key": "evaluate_action",
      "label": "evaluate_action"
    },
    {
      "conditions": [],
      "definition": "The selected Product outcome, with any admitted bounded prerequisite or experiment, supplies external authority for loop work. It is not authored, selected or enlarged by models, gaps, assurance, ledgers or projections.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 803,
          "quote": "Product models, gaps, assurance, ledgers and\nprojections may interpret that outcome but cannot author, select or\nenlarge it. `evaluate_next` may select material work only within that\noutcome or within an admitted bounded prerequisite or experiment.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 800
        }
      ],
      "key": "selected_product_outcome",
      "label": "Selected Product outcome and bounded basis"
    },
    {
      "conditions": [],
      "definition": "Distinct result domains concern candidate availability, exact-basis edge-obligation fulfilment, lawful action selectability for the current gap and exact basis, and candidate acceptance at its declared boundary. Closure decisions and their cause refinements answer the edge predicate; typed no-actions answer the selection predicate; ACTIVATION accept/local_repair/re_enter/reject answer acceptance. Ordinary next-action selections and graph-complete empty selections are invocational data.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1189,
          "quote": "A closure decision is not a disposition and is never recorded\nas one, and no disposition is a closure decision: `repair` is not\n`local_repair`, and `re-enter` is not `re_enter`. Edge closure is\nevidence toward acceptance and never acceptance itself",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 1186
        }
      ],
      "key": "loop_result_domains",
      "label": "Predicate-specific loop results"
    },
    {
      "conditions": [],
      "definition": "The governed work pair consists of mutable workspace W and immutable ledger L of closure-relevant work over W, with immutable event/replay spine E and evaluator work Ev over a declared L snapshot. L contains admitted callout basis, deltas, file refs, digests, execution evidence, touched obligations, claims, evaluator inputs/outputs and admission status, rather than copying W. Ledger 'attention' is a structural analogy: typed, immutable, lineage-constrained, policy-bounded and replayable, not a transformer-attention dependency.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 937,
          "quote": "F_P acts in W.\nAdmission records governed facts in L.\nE orders and anchors L entries with predecessor refs.\nEv evaluates a declared L snapshot, not ambient W.\nEv output is itself F_P work and is admitted back into L/E.\nL/E constrain the next lawful F_P action in W.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.5D%20Constructive%20evaluation%20and%20yield%20loop",
          "start_line": 932
        }
      ],
      "key": "governed_workspace_ledger",
      "label": "Workspace–ledger governed work pair"
    },
    {
      "conditions": [],
      "definition": "Agentic conformance has two distinct halves: an F_P walkthrough proving the declared constitutional process can be followed on real work, and an F_D admission gate deciding whether each produced artifact conforms. These are conformance evidence, not method ratification.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1463,
          "quote": "Conformance has two halves: an F_P proof that the process can be followed,\nand an F_D gate that admits the produced artifacts (P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.7A%20Conforming%20agentic%20development",
          "start_line": 1462
        }
      ],
      "key": "agentic_conformance",
      "label": "Conforming agentic development"
    },
    {
      "conditions": [],
      "definition": "Closure-grade negative proof exercises the supported Product authority path after invalidating its real authority-bearing input, establishing refusal before prohibited effect and absence of successful legacy, fallback, reconstruction or parallel paths. Source, packaged, installed and runtime absence are distinct claims.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1550,
          "quote": "Closure-grade negative evidence identifies the supported entry and the\ngoverning authority; invalidates the real authority-bearing input;\nexercises the supported path; proves refusal before the prohibited\neffect; and establishes that no legacy, fallback, reconstruction or\nparallel path succeeds. Source, packaged, installed and runtime absence\nare distinct claims (P6, P3).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.7B%20Real%20authority-path%20negative%20proof%20%28STDO-UP-010%29",
          "start_line": 1545
        }
      ],
      "key": "authority_path_negative_proof",
      "label": "Real authority-path negative proof"
    },
    {
      "conditions": [],
      "definition": "A cumulative typed environment carries available typed bindings across composition; a later function can require earlier carried bindings rather than only its immediate predecessor's output.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1577,
          "quote": "A later function may\nrequire any typed binding available in the cumulative carried\nenvironment, not only the immediately previous output (P4a, P4b).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F11.%20Core%20law%2F11.8%20Cumulative%20environment%20law%20is%20mandatory",
          "start_line": 1575
        }
      ],
      "key": "cumulative_environment",
      "label": "Cumulative typed environment"
    },
    {
      "conditions": [],
      "definition": "Scenarios are graph-native proving surfaces. Declared scenarios and use cases are described as the best source of significant proving paths because they pressure feature intent and design decisions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1602,
          "quote": "Scenarios are graph-native proving surfaces, not only test\ndocumentation.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F12.%20Scenario%20rule",
          "start_line": 1601
        }
      ],
      "key": "scenario_bundle",
      "label": "Scenario bundle"
    },
    {
      "conditions": [],
      "definition": "ODD §20 is a derived compression of same-digest §1, §2, §11.1–§11.5D, §11.7 and §11.7A. It describes graph-native domain product authoring, typed assets, named functions, catalogue and GTL publication, ABG execution, the constructive loop, history-derived queries, lawful manual traversal, outcome-first construction, yield and deterministically admitted agentic work. It owns no determination.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1804,
          "quote": "Its sources are §1, §2, §11.1 to §11.5D, §11.7 and §11.7A of\nthis member at the same digest, and it owns no determination. Where it and\na source section differ, the source section decides",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F20.%20Canonical%20compression",
          "start_line": 1802
        }
      ],
      "key": "odd_canonical_compression",
      "label": "ODD canonical compression"
    },
    {
      "conditions": [],
      "definition": "ODD's successor provenance register claims receipt of all 48 rc.2 ODD_METHOD rows under STDO-UP-015, restatement at predecessor modal force, exact carriage of formal blocks and tables, successor member naming, equivalent indicative prohibitions, labelled axiom paragraphs and British prose spelling with identifiers preserved. It identifies seven new clauses: two bounded-step/refinement bindings, roles-versus-functor clarification, closure and audit result mappings, foundation-to-law table, and the compression's derived status. Its row for the loop additionally records new no-action result distinctions and closure-versus-acceptance distinctions. Routes are provenance only.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1815,
          "quote": "Rows of rc.2 ODD_METHOD.md received by this member, all 48 under\nSTDO-UP-015. Anchors are into rc.2 ODD_METHOD.md; a locus is a section of\nthis file. Every conserved row is restated in this member's own text at\nthe predecessor's modal force; a route is provenance only. Formal content\n(code blocks and tables) is carried exactly",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ODD.md#ODD%2F21.%20Source%20dispositions",
          "start_line": 1810
        }
      ],
      "key": "odd_source_register",
      "label": "ODD source-disposition register"
    },
    {
      "conditions": [],
      "definition": "A guide owning the governed project's commentary layer: post purpose, authority boundary, location, identity, categories, structure, discussion state, posting rules and ratification. It consumes, without redefining, PRODUCT_DEFINITION's ticketing.comments binding, TICKETS work carriers, SPEC_METHOD authority surfaces and EVALUATION claims/evidence. Shared-method adoption belongs to SPEC_METHOD §6; rc.2 routes are provenance, not application dependencies.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 6,
          "quote": "Guide. Owns the commentary layer of a governed project: what a post is\nfor, its boundary with authority, where posts live, their identity,\ncategories and structure, their discussion state, the posting rules and\nratification.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/POSTING_GUIDE.md#POSTING_GUIDE",
          "start_line": 3
        }
      ],
      "key": "posting_guide",
      "label": "POSTING_GUIDE"
    },
    {
      "conditions": [],
      "definition": "A post is working commentary for analysis, criticism, proposed changes, handoff or repricing confidence. It is not constitutional truth, though it may later influence specification or design.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 31,
          "quote": "A post is not constitutional truth. It is working commentary, and it may\nlater influence specification or design (P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/POSTING_GUIDE.md#POSTING_GUIDE%2F1.%20Position",
          "start_line": 30
        }
      ],
      "key": "post",
      "label": "Post"
    },
    {
      "conditions": [],
      "definition": "The post category set is REVIEW (critique of code, specification, design or another post), STRATEGY (proposed technical or methodological direction), GAP (precise insufficiency or contradiction), SCHEMA (data/event/interface/contract shape), HANDOFF (bounded context or task-state transfer), and MATRIX (explicit option comparison for a decision).",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 89,
          "quote": "- `REVIEW`: critique of code, specification, design or another post;\n- `STRATEGY`: a proposed technical or methodological direction;\n- `GAP`: a precise insufficiency or contradiction;\n- `SCHEMA`: the shape of a data model, event model, interface or contract;\n- `HANDOFF`: a bounded transfer of context or task state; and\n- `MATRIX`: an explicit comparison of options for a decision.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/POSTING_GUIDE.md#POSTING_GUIDE%2F5.%20Categories",
          "start_line": 84
        }
      ],
      "key": "post_categories",
      "label": "Post categories"
    },
    {
      "conditions": [],
      "definition": "The base post template has '# {CATEGORY}: {Subject}', Author {agent}, Date {ISO 8601}, Addresses {artifact, issue, or boundary under discussion}, Status Draft, optional Updated {ISO 8601}, and Summary, Analysis and Recommended Action sections. MATRIX replaces central free prose with a decision table. This is a represented document shape, not a created post.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 111,
          "quote": "# {CATEGORY}: {Subject}\n\n**Author**: {agent}\n**Date**: {ISO 8601}\n**Addresses**: {artifact, issue, or boundary under discussion}\n**Status**: Draft\n**Updated**: {ISO 8601, optional}\n\n## Summary\n{short summary}\n\n## Analysis\n{main content}\n\n## Recommended Action\n{next step}",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/POSTING_GUIDE.md#POSTING_GUIDE%2F6.%20Structure",
          "start_line": 96
        }
      ],
      "key": "post_template",
      "label": "Post base shape"
    },
    {
      "conditions": [],
